  const matchingInspection=inspection&&sameObservation(sharedEvent,inspection.event)?inspection:null;
  const portfolio=currentRecord?.portfolio??activePortfolio;
  const portfolioChanged=Boolean(currentRecord&&((currentRecord.portfolioReference&&(currentRecord.portfolioReference.id!==inventories.activeId||currentRecord.portfolioReference.revision!==inventories.active?.revision))||JSON.stringify(currentRecord.portfolio)!==JSON.stringify(activePortfolio)));
  const saved=Boolean(record&&history.some(item=>item.id===record.id));
  const rows=currentRecord?.rows??[];
  const ordered=useMemo(()=>filterExposure(rows,currentRecord?.settings.threshold??4,{status:filter,currency,query,region,businessLine}),[rows,currency,filter,query,region,businessLine,currentRecord?.settings.threshold]);
  const selectedRow=ordered.find(row=>row.id===selected);
  const hasViewFilters=filter!=='all'||currency!=='all'||query.trim()!==''||region!==null||businessLine!==null;
  function clearViewFilters(){setFilter('all');setCurrency('all');setQuery('');setRegion(null);setBusinessLine(null);setPage(0);}
  const totals=Object.entries(currentRecord?.summary.knownValueByCurrency??{});
